title = #{title}, author = #{author}, publisher = #{publisher}, isbn = #{isbn}, category_id = #{categoryId}, original_price = #{originalPrice}, price = #{price}, `condition` = #{condition}, description = #{description}, cover_image = #{coverImage}, stock = #{stock}, status = #{status},
WHERE id = #{id}
